    const bodyIndex = snakeIndex.get(key);
    const isHead = key === headKey;
    const isBody = bodyIndex !== undefined && bodyIndex > 0;
    const isObstacle = obstacleSet.has(key);
    const isPacket = key === packetKey;
    const alternate = (x + y) % 2 === 1;
